// Keep only valid records and build clean rows with exactly the storage columns.
const rows = [];

for (const item of $input.all()) {
  const d = item.json || {};

  // Process only records where valid === true; ignore everything else.
  if (d.valid !== true) continue;

  rows.push({
    json: {
      paper_id: d.paper_id != null ? String(d.paper_id) : null,
      topic: d.topic != null ? d.topic : null,
      title: d.title != null ? d.title : null,
      authors: d.authors != null ? d.authors : null,
      year: typeof d.year === 'number' ? d.year : (d.year ? Number(d.year) : null),
      venue: d.venue != null ? d.venue : null,
      citation_count: typeof d.citation_count === 'number' ? d.citation_count : (d.citation_count != null ? Number(d.citation_count) : null),
      external_ids: typeof d.external_ids === 'string'
        ? d.external_ids
        : (d.external_ids != null ? JSON.stringify(d.external_ids) : null),
      publication_types: typeof d.publication_types === 'string'
        ? d.publication_types
        : (d.publication_types != null ? JSON.stringify(d.publication_types) : null),
      claim: d.claim != null ? d.claim : null,
      stance: d.stance != null ? d.stance : null,
      confidence: typeof d.confidence === 'number' ? d.confidence : (d.confidence != null ? Number(d.confidence) : null),
      methodology_type: d.methodology_type != null ? d.methodology_type : null,
      methodology_score: typeof d.methodology_score === 'number' ? d.methodology_score : (d.methodology_score != null ? Number(d.methodology_score) : null),
      sample_size: (d.sample_size === undefined ? null : d.sample_size),
      key_limitation: d.key_limitation != null ? d.key_limitation : null,
      authors_normalized: Array.isArray(d.authors_normalized)
        ? JSON.stringify(d.authors_normalized)
        : (d.authors_normalized != null ? String(d.authors_normalized) : null),
    },
  });
}

return rows;

// Postgres insert with skipOnConflict returns only the rows actually inserted.
// Rows whose paper_id already existed are skipped and not returned.
const insertedRows = $input.all().filter((i) => i.json && Object.keys(i.json).length > 0);
const papers_inserted = insertedRows.length;

// Total valid rows that were attempted for insertion.
let totalAttempted = 0;
try {
  totalAttempted = $('Prepare Valid Rows').all().length;
} catch (e) {
  totalAttempted = papers_inserted;
}

const papers_skipped = Math.max(totalAttempted - papers_inserted, 0);

return [{ json: { papers_inserted, papers_skipped } }];
